bad = []
def chk(t, where):
    if '…' in t or '...' in t.replace('....', '').replace('.......', '') and re.search(r'(?<!\.)\.{3}(?!\.)', t): bad.append(where + ' 점 3개/…: ' + t)
    for m in re.finditer(r'\.{2,}', t):
        n = len(m.group(0)); end = re.match(r'[」』)\]”’"\']*[?!]*\s*$', t[m.end():])
        if n != (7 if end else 4): bad.append(f'{where} 점 {n}개: {t}')
def walk(o, p=''):
    if isinstance(o, str): chk(o, p)
    elif isinstance(o, list): [walk(v, f'{p}[{i}]') for i, v in enumerate(o)]
    elif isinstance(o, dict): [walk(v, p + '.' + k) for k, v in o.items()]
